func:
// [WP Update] voorbereiding Admin API GET /flows
// phase: "check" of "apply" (komt via msg.topic van de knop)
// Inloggegevens: eerst de dashboard-velden, anders omgevingsvariabelen
// WPU_ADMIN_USER / WPU_ADMIN_PASS. Dat is de veilige route: geen wachtwoord
// in de editor of in de Node-RED context (alleen in de container-omgeving).
// uit1: rechtstreeks GET /flows | uit2: eerst POST /auth/token
const c = flow.get("WPU_cfg") || {};
const base = adminBase();
const phase = (msg.topic === "apply") ? "apply" : "check";
const uiUser = (c.user !== undefined && c.user !== null) ? String(c.user).trim() : "";
// wachtwoord uit de session-only memory store (nooit op disk)
const uiPassRaw = flow.get("WPU_pass", "memory");
const uiPass = (uiPassRaw !== undefined && uiPassRaw !== null) ? String(uiPassRaw) : "";
const user = uiUser || (env.get("WPU_ADMIN_USER") || "");
const pass = uiPass || (env.get("WPU_ADMIN_PASS") || "");

function authHeader(tok) {
    const h = { "Node-RED-API-Version": "v2" };
    if (tok) { h["Authorization"] = "Bearer " + tok; }
    return h;
}
function getFlowsMsg(tok) {
    return {
        _phase: phase, _base: base,
        url: base + "/flows", method: "GET",
        headers: authHeader(tok), payload: ""
    };
}

// Direct verder als geen inlog of een vers token (max 1 uur: admin-tokens
// vervallen server-side; vooruit verversen voorkomt een 401 midden in een keten)
if (!user) { return [getFlowsMsg(null), null]; }
// admin-token (bearer met admin-rechten) alleen in de memory store
let token = flow.get("WPU_token", "memory");
const tokenTime = flow.get("WPU_tokenTime", "memory");
if (token) {
    if (tokenTime && (Date.now() - tokenTime > 60 * 60 * 1000)) {
        flow.set("WPU_token", null, "memory");
        flow.set("WPU_tokenTime", null, "memory");
        token = null;
    } else {
        return [getFlowsMsg(token), null];
    }
}

// Eerst een token halen
const tokenMsg = {
    _phase: phase, _base: base,
    url: base + "/auth/token", method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: {
        client_id: "node-red-admin",
        grant_type: "password",
        scope: "*",
        username: user,
        password: pass
    }
};
return [null, tokenMsg];

function adminBase() {
    // Server-side alleen: loopback (deze flow draait in Node-RED zelf) of de
    // omgevingsvariabele WPU_ADMIN_BASE. NOOIT uit een dashboard-veld: dan
    // zouden WPU_ADMIN_USER/PASS naar een willekeurige URL gestuurd kunnen
    // worden door iemand met alleen dashboard-toegang.
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}

// [WP Update] antwoord van POST /auth/token verwerken, dan door naar GET /flows
const p = msg.payload || {};
if (msg.statusCode === 200 && p.access_token) {
    // token alleen in de memory store: nooit in de persistente context op disk
    flow.set("WPU_token", p.access_token, "memory");
    flow.set("WPU_tokenTime", Date.now(), "memory");
    const out = {
        _phase: msg._phase, _base: msg._base,
        url: msg._base + "/flows", method: "GET",
        headers: { "Node-RED-API-Version": "v2", "Authorization": "Bearer " + p.access_token },
        payload: ""
    };
    return [out, null];
}
// token mislukt: niet direct stoppen, maar duidelijke fout
return [null, { payload: "Admin-login mislukt (status " + msg.statusCode + "). Controleer user/wachtwoord-velden. Let op: bij adminAuth zonder credentials-type werkt Node-RED met API-keys, dan kun je het beste zonder inlog draaien op het LAN.", topic: "WP Update fout" }];

// [WP Update] GET /flows verwerken
// uit1 (check): huidige versie tonen, dan version.json ophalen
// uit2 (apply): nieuwe flow.json downloaden
// uit3 (fout): foutmelding
const st = flow.get("WPU") || {};
const raw = msg.payload;
const isV2 = !Array.isArray(raw) && raw && Array.isArray(raw.flows);
const flows = isV2 ? raw.flows : (Array.isArray(raw) ? raw : null);
if (msg.statusCode === 401) {
    flow.set("WPU_token", null, "memory");
    flow.set("WPU_tokenTime", null, "memory");
    return [null, null, { payload: "Admin-login geweigerd (401): token vervallen of inlog gewijzigd. Druk opnieuw op de knop; er wordt dan automatisch een nieuw token opgehaald.", topic: "WP Update fout" }];
}
if (!flows) {
    return [null, null, { payload: "Kan de eigen flows niet ophalen via de Admin API (status " + msg.statusCode + "). Check WPU_ADMIN_BASE (omgeving): voorbeeld http://127.0.0.1:1880", topic: "WP Update fout" }];
}
const rev = isV2 ? raw.rev : null;
st.rev = rev;
st.apiV2 = isV2;

// Actuele versie uit de changelog-node ("Line - Changelog": "Version 26.5.1 Stable")
let cur = null;
for (let i = 0; i < flows.length; i++) {
    const n = flows[i];
    if (n && n.name === "Line - Changelog" && typeof n.format === "string") {
        const m = /Version (\d+\.\d+\.\d+)/.exec(n.format);
        if (m) { cur = m[1]; break; }
    }
}
// fallback: elke node met "changelog" in de naam (een hernoemde node breekt
// dan niet de versieherkenning)
if (!cur) {
    for (let i = 0; i < flows.length; i++) {
        const n = flows[i];
        if (!n || !/changelog/i.test(String(n.name || ""))) { continue; }
        const fields = ["format", "info", "label"];
        for (let j = 0; j < fields.length; j++) {
            const v = n[fields[j]];
            if (typeof v === "string") {
                const m = /Version (\d+\.\d+\.\d+)/.exec(v);
                if (m) { cur = m[1]; break; }
            }
        }
        if (cur) { break; }
    }
}
st.currentVersion = cur;
flow.set("WPU", st);
// grote blob alléén in de geheugenstore (voorkomt MB-schrijfacties naar disk)
flow.set("WPU_localFlows", flows, "memory");
node.status({ text: "Huidige versie: " + (cur || "onbekend") });

const curText = cur || "onbekend";
msg._phase = msg._phase || "check";
if (msg._phase === "apply") {
    if (!st.latest || !st.latest.flowUrl) {
        return [null, null, { payload: "Eerst [Controleer op update] drukken: de tab moet weten waar de nieuwe versie te halen is.", topic: "WP Update fout" }];
    }
    if (st.latest.checkedAt && (Date.now() - st.latest.checkedAt > 60 * 60 * 1000)) {
        return [null, null, { payload: "Update gestopt: de laatste versie-check is ouder dan een uur, versie " + st.latest.version + " kan verouderd zijn. Druk eerst op [Controleer op update] en daarna opnieuw op [UPDATE UITVOEREN].", topic: "WP Update fout" }];
    }
    const out = {
        _phase: "apply", _base: msg._base,
        url: st.latest.flowUrl, method: "GET", // v4.4.1: al genormaliseerd bij opslag; encodeUri hier gaf %2520 = live-404
        headers: {}, payload: ""
    };
    return [null, out, null];
}
// check-vertakking: versie-info ophalen
const out = {
    _phase: "check", _base: msg._base, _cur: curText,
    url: "https://raw.githubusercontent.com/edterbak/HeishaMoNR/main/version.json",
    method: "GET", headers: {}, payload: ""
};
return [out, null, null];

// [WP Update] versies vergelijken (na het ophalen van version.json)
// uit1: veld "Geïnstalleerd" | uit2: veld "Beschikbaar" | uit3: toast/status
// uit4: als version.json ontbreekt -> repo-scan (fallback)
const st = flow.get("WPU") || {};
const cur = msg._cur || st.currentVersion || "onbekend";
const v = msg.payload;
if (msg.statusCode !== 200 || !v || !v.version) {
    // version.json nog niet door de repo aangeboden: via de gewone repo-pagina scannen
    return [ { payload: cur }, { payload: "-" }, null,
        { url: "https://github.com/edterbak/HeishaMoNR", method: "GET",
          headers: { "User-Agent": "HeishaMoNR-WP-Update-tab" }, payload: "" } ];
}
if (!/^\d+\.\d+\.\d+$/.test(String(v.version))) {
    return [ { payload: cur }, { payload: "-" },
        { payload: "version.json bevat een onverwacht versie-formaat (\"" + v.version + "\"); alleen X.Y.Z (stable) wordt ondersteund.", topic: "WP Update fout" },
        null ];
}
const fq = normUrl(v.flowUrl);
if (!/^https:\/\/raw\.githubusercontent\.com\/edterbak\/HeishaMoNR\//.test(fq)) {
    return [ { payload: cur }, { payload: "-" },
        { payload: "version.json bevat een flowUrl buiten de HeishaMoNR-repo (" + v.flowUrl + "); download geweigerd.", topic: "WP Update fout" },
        null ];
}
st.latest = { version: v.version, flowUrl: fq, notes: v.notes || "", checkedAt: Date.now() };
flow.set("WPU", st);
const curKnown = !!(cur && cur !== "onbekend");
if (!curKnown) {
    return [ { payload: cur }, { payload: v.version },
        { payload: "Huidige versie onbekend (geen changelog-node gevonden); beschikbaar: " + v.version + ". [UPDATE UITVOEREN] werkt wel (met de 1-uurscheck), maar controleer handmatig of de update echt nodig is." + (v.notes ? " Notes: " + v.notes : ""), topic: "WP Update" },
        null ];
}
if (isNewerVersion(cur, v.version)) {
    return [ { payload: cur }, { payload: v.version + " (update!)" },
        { payload: "Update beschikbaar: " + v.version + ". Maak eerst een [Backup settings], druk daarna op [UPDATE UITVOEREN]." + (v.notes ? " Notes: " + v.notes : ""), topic: "WP Update" },
        null ];
}
return [ { payload: cur }, { payload: v.version },
    { payload: "Je draait al de nieuwste versie (" + cur + ").", topic: "WP Update" },
    null ];

function normUrl(u) {
    // v4.4.1: spaties -> %20, bestaande procent-encoding (done by de repo-scan) blijft intact
    return String(u).replace(/%(?![0-9A-Fa-f]{2})/g, "%25").replace(/ /g, "%20");
}
function isNewerVersion(a, b) {
    //fy onbekend is NIET "ouder": dan zou elke check een phantom-update melden
    if (!a || a === "onbekend") { return false; }
    const pa = String(a).split(".").map(Number);
    const pb = String(b).split(".").map(Number);
    for (let i = 0; i < 3; i++) {
        const x = pa[i] || 0, y = pb[i] || 0;
        if (y > x) { return true; }
        if (y < x) { return false; }
    }
    return false;
}

// [WP Update] nieuwe flow.json binnengekomen; nu palette-info (GET /nodes) ophalen
const st = flow.get("WPU") || {};
if (!Array.isArray(msg.payload)) {
    return [null, { payload: "Download van de nieuwe flow.json mislukt (status " + msg.statusCode + ") via " + msg.url + ". Klopt de repo (flows (X.Y.Z stable).json in de root) of de flowUrl in version.json?", topic: "WP Update fout" }];
}
flow.set("WPU_newFlows", msg.payload, "memory");
// integriteit: de changelog-node in het bestand moet de verwachte versie melden
let newVers = null;
for (const n of msg.payload) {
    if (n && n.name === "Line - Changelog" && typeof n.format === "string") {
        const m = /Version (\d+\.\d+\.\d+)/.exec(n.format);
        if (m) { newVers = m[1]; break; }
    }
}
if (newVers && st.latest && st.latest.version && newVers !== st.latest.version) {
    return [null, { payload: "Download-verificatie mislukt: de gedownloade flow meldt versie " + newVers + " terwijl versie " + st.latest.version + " verwacht werd (changelog-node). Download geweigerd; er is niets gewijzigd.", topic: "WP Update fout" }];
}
const base = adminBase();
// GET /nodes geeft alléén JSON bij Accept: application/json (editor-api v4/v5); zonder Accept krijg je de HTML-configblob
const headers = { "Node-RED-API-Version": "v2", "Accept": "application/json" };
const tok = flow.get("WPU_token", "memory");
if (tok) { headers["Authorization"] = "Bearer " + tok; }
msg.url = base + "/nodes";
msg.method = "GET";
msg.headers = headers;
msg.payload = "";
return [msg, null];

function adminBase() {
    // Server-side alleen: loopback (deze flow draait in Node-RED zelf) of de
    // omgevingsvariabele WPU_ADMIN_BASE. NOOIT uit een dashboard-veld: dan
    // zouden WPU_ADMIN_USER/PASS naar een willekeurige URL gestuurd kunnen
    // worden door iemand met alleen dashboard-toegang.
    const b = (env.get("WPU_ADMIN_BASE") || "").trim();
    if (b) { return b.replace(/\/+$/, ""); }
    let root = "";
    try { root = (RED.settings && RED.settings.httpAdminRoot) || ""; } catch (e) { root = ""; }
    return ("http://127.0.0.1:1880" + root).replace(/\/+$/, "");
}

// ============================================================================
// [WP Update] DE KERN: id-gebaseerde merge van het WP-package
// Werkt op basis van stabiele node-ids (geverifieerd 26.3.1 -> 26.5.1), met
// vangnetten voor het geval Ed ooit een release met VOLLEDIG nieuwe ids uitbrengt:
//   - flow-tabs worden behalve op id ook op LABEL herkend ("WP Dash", ...;
//     labels zijn tot nu toe nooit gewijzigd); een herbouwde package ruimt
//     de oude tabs dan alsnog op
//   - koppelt de nieuwe package een NIET-geconfigureerde placeholder-broker
//     (host "x.x.x.x"), dan worden alle mqtt-referenties herschreven naar de
//     lokaal meest-gebruikte broker (voorkomt stille MQTT-brei na rebuild)
// Verdere regels (id-stabil scenario):
//   1. Nodes binnen package-tabs: lokale definitie vervangen door de nieuwe.
//   2. Package-config-nodes op id: idem, BEHALVE mqtt-broker: de lokale broker
//      wint ALTÍJD (jouw host/poort blijft staan).
//   3. Lokaal geconfigureerde broker-referenties in package mqtt-nodes blijven
//      de referentie van de lokale versie (voorkomt kapotte 'missing config').
//   4. Alles buiten het package: onaangeroerd.
//   5. Singleton-configs (global-config ui_base): alleen de package-versie.
//   6. Pre-flight: palette-check en duplicaat-id-check vóór de POST.
//   7. Rapportage van achtergebleven verdachte oude items (niet automatisch
//      verwijderd; zie _orphanUiTabs / _suspectTabs; alleen bij een id-rebuild).
// ============================================================================
const st = flow.get("WPU") || {};
// grote blobs alléén in de geheugenstore (memory): geen MB-persistent-schrijfacties
const local = flow.get("WPU_localFlows", "memory");
const newPkg = flow.get("WPU_newFlows", "memory");
const errMsg = (t) => [null, { payload: t, topic: "WP Update fout" }, null];

if (!Array.isArray(local) || !Array.isArray(newPkg)) {
    return errMsg("Interne fout: lokale flows of nieuwe package ontbreken. Opnieuw: [Controleer] en [UPDATE UITVOEREN].");
}

// ---- 1. Palette-check ----
// GET /nodes: platte lijst node-sets met types[] (editor-api/registry), alléén
// JSON bij Accept: application/json (staat op de /nodes-aanvraag). Sets met
// err of enabled=false tellen niet mee. tab/subflow/group/junction en
// subflow:<id> zijn flow-config-types en zitten nooit in /nodes.
const BUILTIN = new Set(["tab", "subflow", "group", "junction"]);
const sets = msg.payload;
const available = new Set();
if (!Array.isArray(sets)) {
    if (msg.statusCode === 401) {
        flow.set("WPU_token", null, "memory");
        flow.set("WPU_tokenTime", null, "memory");
        return errMsg("Admin-login geweigerd (401) bij het ophalen van de palette-info. Druk opnieuw op [Controleer op update] en [UPDATE UITVOEREN]; er wordt dan een nieuw token gehaald.");
    }
    return errMsg("Kan de palette-info niet lezen (GET /nodes gaf geen lijst; status " + msg.statusCode + "). Controleer WPU_ADMIN_BASE of meld dit als bug.");
}
for (const s of sets) {
    const entries = (s && Array.isArray(s.nodes)) ? s.nodes : [s];
    for (const e of entries) {
        if (!e || e.err || e.enabled === false) { continue; }
        const types = Array.isArray(e.types) ? e.types : (e.type ? [e.type] : []);
        for (const t of types) { available.add(t); }
    }
}
const missing = [];
for (const n of newPkg) {
    if (!n.type || BUILTIN.has(n.type) || n.type.indexOf("subflow:") === 0) { continue; }
    if (!available.has(n.type) && missing.indexOf(n.type) === -1) {
        missing.push(n.type);
    }
}
if (missing.length > 0) {
    return errMsg("Kan niet updaten: node-type(s) ontbreken in de palette: " + missing.join(", ") + ". Installeer eerst de benodigde Node-RED libraries (zie repo-documentatie).");
}

// ---- 2. Scope bepalen ----
const pkgIds = new Set(newPkg.map(n => n.id));
const pkgTabs = newPkg.filter(n => n.type === "tab" || n.type === "subflow");
const pkgTabIds = new Set(pkgTabs.map(n => n.id));
// label van een tab, naam van een subflow (subflows hebben name, geen label)
const tabLabel = (t) => String((t.type === "subflow" ? (t.name || t.label) : (t.label || t.name)) || "").trim();
const pkgTabLabels = new Set(pkgTabs.map(tabLabel).filter(Boolean));

// Lokale flow-tabs die qua LABEL bij de package horen (rebuild-vingnet).
// Per-label beleid: een label-match ruimt alléén op als GEEN enkele lokale tab
// met dat label op ID met de package matcht (echte id-rebuild). Bij een
// id-stabiele release matcht de package-tab al op id; een extra, persoonlijke
// tab met toevallig hetzelfde label blijft dan gegarandeerd staan.
const doomedLocalTabs = new Set();
const labelTabs = new Map();
for (const n of local) {
    if (n.type === "tab" || n.type === "subflow") {
        const L = tabLabel(n);
        if (pkgTabLabels.has(L)) {
            if (!labelTabs.has(L)) { labelTabs.set(L, { ids: [], onId: 0 }); }
            const e = labelTabs.get(L);
            e.ids.push(n.id);
            if (pkgTabIds.has(n.id)) { e.onId++; }
        }
    }
}
for (const e of labelTabs.values()) {
    if (e.onId === 0) { for (const id of e.ids) { doomedLocalTabs.add(id); } }
}

// ---- 3. Brokers in kaart ----
const localBrokers = new Set();
for (const n of local) { if (n.type === "mqtt-broker") { localBrokers.add(n.id); } }
// lokale broker-referenties binnen de oude package (id-stabil scenario)
const localBrokerRef = new Map();
for (const n of local) {
    const inPkg = pkgIds.has(n.id) || (n.z && (pkgTabIds.has(n.z) || doomedLocalTabs.has(n.z))) || doomedLocalTabs.has(n.id);
    if (inPkg && n.broker) { localBrokerRef.set(n.id, n.broker); }
}
// de lokaal meest-gebruikte broker = de "levende" broker (rebuild-vingnet)
const usage = {};
for (const n of local) {
    if (n.broker) { usage[n.broker] = (usage[n.broker] || 0) + 1; }
}
let liveBroker = null, liveMax = -1;
for (const id of Object.keys(usage)) {
    if (usage[id] > liveMax && localBrokers.has(id)) { liveMax = usage[id]; liveBroker = id; }
}
// package broker-definities (om placeholders te herkennen)
const pkgBrokerDefs = new Map();
for (const n of newPkg) { if (n.type === "mqtt-broker") { pkgBrokerDefs.set(n.id, n); } }

// lokale global-config-env bewaren: de omgevingsvariabelen van de gebruiker
// mogen niet verloren gaan als de package een eigen global-config meebrengt
let localGlobalEnv = null;
for (const n of local) {
    if (n.type === "global-config" && Array.isArray(n.env) && n.env.length > 0) { localGlobalEnv = n.env; }
}

// ---- 4. Lokale nodes: package-gedeelte weg (behalve de lokale broker) ----
const result = [];
for (const n of local) {
    const inPkg = pkgIds.has(n.id) || doomedLocalTabs.has(n.id) ||
        (n.z && (pkgTabIds.has(n.z) || doomedLocalTabs.has(n.z)));
    if (!inPkg) { result.push(n); continue; }
    if (n.type === "mqtt-broker") { result.push(n); }
}

// ---- 5. Nieuwe package-definities toevoegen ----
const pendingBrokers = [];
for (const n of newPkg) {
    if (n.type === "mqtt-broker") {
        if (localBrokers.has(n.id)) { continue; }
        pendingBrokers.push(n);
        continue;
    }
    const def = JSON.parse(JSON.stringify(n));
    if (def.broker) {
        const pkgDef = pkgBrokerDefs.get(def.broker);
        if (pkgDef && pkgDef.broker === "x.x.x.x" && liveBroker) {
            def.broker = liveBroker; // vangnet: niet-geconfigureerde package-broker
        } else if (localBrokerRef.has(n.id) && localBrokers.has(localBrokerRef.get(n.id))) {
            def.broker = localBrokerRef.get(n.id); // lokale referentie behouden
        }
    }
    if (def.type === "global-config" && localGlobalEnv) {
        // env samenvoegen: lokale entries winnen, nieuwe package-entries komen erbij
        const merged = localGlobalEnv.slice();
        for (const pe of (def.env || [])) {
            if (!merged.some(le => le.name === pe.name)) { merged.push(pe); }
        }
        def.env = merged;
    }
    result.push(def);
}
for (const b of pendingBrokers) {
    const used = result.some(n => n && n.broker === b.id);
    if (used) { result.push(b); }
}

// ---- 6. Singleton-config types: alleen de package-versie ----
const SINGLETONS = ["global-config", "ui_base"];
const pkgSingletons = {};
for (const n of newPkg) { if (SINGLETONS.indexOf(n.type) !== -1) { pkgSingletons[n.type] = true; } }
for (let i = result.length - 1; i >= 0; i--) {
    const n = result[i];
    if (pkgSingletons[n.type] && !pkgIds.has(n.id)) { result.splice(i, 1); }
}

// ---- 7. Sanity: geen duplicaat-ids ----
const seen = new Set();
for (const n of result) {
    if (seen.has(n.id)) { return errMsg("Interne fout: duplicaat node-id na merge: " + n.id + ". NIET gepusht; meld dit als bug."); }
    seen.add(n.id);
}

// ---- 8. Rapport: achtergebleven oude items ----
// ui_tab-labels van de nieuwe package ("Home", "Settings", ...): te generiek om
// automatisch te verwijderen, dus alleen MELDEN, en alléén als er een duidelijke
// id-REBUILD speelt (doomedLocalTabs > 0). In een id-stabiele merge heeft een
// persoonlijk tabblad met toevallig dezelfde naam niks te zoeken in de melding.
const newUiTabNames = new Set(newPkg.filter(n => n.type === "ui_tab").map(n => String(n.name || "").trim()));
// echte id-rebuild = label-match ZONDER id-match (bij id-stabiele merges vallen
// alle label-matches samen met id-matches en is dit nul)
const rebuildDetected = Array.from(doomedLocalTabs).some(id => !pkgIds.has(id));
const orphanUiTabs = [];
if (rebuildDetected) {
    for (const n of result) {
        if (n.type === "ui_tab" && !pkgIds.has(n.id) && newUiTabNames.has(String(n.name || "").trim())) {
            orphanUiTabs.push(n.name || n.id);
        }
    }
}
